import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine());
        int somme = 0;
        int compte = 0;
        for (int i = 1; i <= n; i++) {
            if (i % 2 == 0) {
                somme += i;
                compte++;
            }
        }
        System.out.println("Somme : " + somme);
        System.out.println("Pairs : " + compte);
    }
}

